    schema, err := preparedUpgradeSchema(db)
    if err != nil || schema != sourceSchema { return fmt.Errorf("PREPARED_UPGRADE_ROLLBACK_SCHEMA") }
    tx, err = db.BeginTx(ctx, nil)
